// Offline support (sw.js is generated by `npm run web:build`). Only the exported site has its
// scripts under /_expo/static: the dev server must not be cached. A separate file rather than an
// inline script, so the Content-Security-Policy can forbid inline scripts.
addEventListener('load', function () {
  if (
    'serviceWorker' in navigator &&
    document.querySelector('script[src*="/_expo/static/js/web/"]')
  ) {
    // Offline the update check fails; the stored version keeps working.
    navigator.serviceWorker.register('/sw.js').catch(function () {});
  }
});
